mapper.sql:
SELECT * FROM (SELECT t2.id,T.MOULD_CODE,#{year} year,#{month} month, t2.factory_code, t2.mould_status, t2.specifications_pattern, t2.ower_factory_code, t2.specifications, t2.pattern, t2.mould_type, t2.create_time, t2.update_time, t2.create_by, t2.update_by, t2.remark FROM t_mdm_product_model_relation T left JOIN ( select t.id, t.year, t.month, t.factory_code, t.mould_code, t.mould_status, CONCAT_WS('', m.specifications, m.pattern) as specifications_pattern, m.factory_code ower_factory_code, m.specifications, m.pattern, m.mould_type, t.create_time, t.update_time, t.create_by, t.update_by, t.remark from T_MDM_MOULD_USE_STATUS t left join T_MDM_MOULD_INFO m on t.mould_code=m.mould_code
and t.year = #{year} and t.month = #{month} and t.factory_code = #{factoryCode} and t.mould_status = #{mouldStatus}
and CONCAT_WS('', m.specifications, m.pattern) like concat(#{specificationsPattern},'%')
${params.dataScope}
) T2 ON T.MOULD_CODE=T2.MOULD_CODE WHERE T.PRODUCT_CODE=#{productCode} and t.mould_code like concat(#{mouldCode},'%') ) as t

select.where:
and id != #{id}
and year = #{year}
and month = #{month}
and mould_code = #{mouldCode}
and FACTORY_CODE = #{factoryCode}

    and (1, mould_code) in

        (1, #{item})



${params.dataScope}

mapper.delete:
delete from T_MDM_MOULD_USE_STATUS
where
year=#{year,jdbcType=DECIMAL} and month=#{month,jdbcType=DECIMAL}

    and factory_code = #{factoryCode}

delete from T_MDM_MOULD_USE_STATUS where MOULD_CODE = #{mouldCode}
                           AND FACTORY_CODE = #{factoryCode}
                           AND YEAR = #{year}
                           AND MONTH = #{month}

mapper.select:
SELECT t1.ID, t1.YEAR AS year, t1.MONTH AS month, t1.FACTORY_CODE AS factoryCode, t1.MOULD_STATUS AS mouldStatus, t1.MOULD_CODE AS mouldCode, t1.OWER_FACTORY_CODE AS owerFactoryCode, t1.SPECIFICATIONS AS specifications, t1.PATTERN AS pattern, t1.MOULD_TYPE AS mouldType, t1.REMARK AS remark FROM T_MDM_MOULD_USE_STATUS t1 LEFT JOIN T_MDM_MOULD_INFO t2 ON t1.MOULD_CODE = t2.MOULD_CODE AND t1.FACTORY_CODE = t2.FACTORY_CODE WHERE t1.FACTORY_CODE = #{factoryCode} AND t1.YEAR = #{year} AND t1.MONTH = #{month} AND t2.MOULD_STATUS = 1
AND t1.MOULD_CODE IN
#{mouldCode}

SELECT mmus.MOULD_CODE,
       mmi.MOULD_NO
  FROM T_MDM_MOULD_USE_STATUS mmus
LEFT JOIN T_MDM_MOULD_INFO mmi
    ON mmus.MOULD_CODE = mmi.MOULD_CODE
   AND mmus.FACTORY_CODE = mmi.FACTORY_CODE
 WHERE mmi.MOULD_STATUS = 1
   AND mmus.MOULD_STATUS = 1
   AND mmus.YEAR = #{year,jdbcType=DECIMAL}
   AND mmus.MONTH = #{month,jdbcType=DECIMAL}
   AND mmus.FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR}
